SELECT o.original_writer_xid::pg_catalog.text AS original_writer_xid, o.operation_ordinal::pg_catalog.text AS operation_ordinal, o.operation_kind::pg_catalog.text AS operation_kind, o.phase::pg_catalog.text AS phase, o.effect_generation::pg_catalog.text AS effect_generation, o.readiness_generation::pg_catalog.text AS readiness_generation, o.sealed_generation::pg_catalog.text AS sealed_generation, o.application_generation::pg_catalog.text AS application_generation, pg_catalog.encode(o.original_context_bytes, 'hex') AS original_context_bytes_hex, pg_catalog.encode(o.original_definition_bytes, 'hex') AS original_definition_bytes_hex, pg_catalog.encode(o.original_input_bytes, 'hex') AS original_input_bytes_hex, pg_catalog.encode(o.original_prestate_bytes, 'hex') AS original_prestate_bytes_hex, pg_catalog.encode(o.admitted_candidate_bytes, 'hex') AS admitted_candidate_bytes_hex, pg_catalog.encode(o.effect_obligation_bytes, 'hex') AS effect_obligation_bytes_hex, pg_catalog.encode(o.original_group_custody_bytes, 'hex') AS original_group_custody_bytes_hex, pg_catalog.encode(o.application_result_bytes, 'hex') AS application_result_bytes_hex FROM truss.row_home_operation o WHERE o.original_writer_xid = $1::pg_catalog.text::pg_catalog.xid8; SELECT t.transaction_id::pg_catalog.text AS transaction_id, t.owner_kind::pg_catalog.text AS owner_kind, t.owner_id::pg_catalog.text AS owner_id, t.owner_discriminator_id::pg_catalog.text AS owner_discriminator_id, t.property_owner_type_id::pg_catalog.text AS property_owner_type_id, t.property_id::pg_catalog.text AS property_id, t.dirty_generation::pg_catalog.text AS dirty_generation, t.sealed_generation::pg_catalog.text AS sealed_generation, pg_catalog.encode(t.original_layout_bytes, 'hex') AS original_layout_bytes_hex, pg_catalog.encode(t.original_home_bytes, 'hex') AS original_home_bytes_hex, pg_catalog.encode(t.original_owner_property_bytes, 'hex') AS original_owner_property_bytes_hex, pg_catalog.encode(t.original_operation_bytes, 'hex') AS original_operation_bytes_hex FROM truss.row_home_touch t WHERE t.transaction_id = $1::pg_catalog.text::pg_catalog.xid8